pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 probe) public {
        // keep the fuzz domain wide; the deciding observation is c's public paused() getter
        vm.assume(probe < type(uint256).max);

