pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        // Minimal config stand-in so role checks (onlyLRTManager/onlyLRTAdmin) succeed:
        // it grants every role to every caller. Wire it into c's `lrtConfig` (slot 0).
        MockLRTConfig cfg = new MockLRTConfig();
        vm.store(address(c), bytes32(uint256(0)), bytes32(uint256(uint160(address(cfg)))));
    }

    function testFuzz_property(address manager, address admin) public {
        vm.assume(manager != address(0) && admin != address(0));

        // General rule: for ANY manager and ANY admin, pausing is reversible —
        // a successful pause() must be followed by a non-reverting unpause() by the admin.
        vm.prank(manager);
        c.pause();

        bool ok;
        vm.prank(admin);
        try c.unpause() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference C: unpause always succeeds (paused() truthfully reports true after pause).
        // Mutant: paused() hardcodes false, so the whenPaused guard fails and unpause reverts.
        assertTrue(ok);
    }
}

