// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        MockConfig cfg = new MockConfig();
        c.initialize(address(cfg));
    }

    function testFuzz_property(address manager) public {
        vm.assume(manager != address(0));
        vm.prank(manager);
        bool firstOk;
        try c.pause() { firstOk = true; } catch { firstOk = false; }
        assertTrue(firstOk, "first pause by manager must succeed");
        vm.prank(manager);
        bool secondOk;
        try c.pause() { secondOk = true; } catch { secondOk = false; }
        // General rule: once the manager successfully pauses, a second pause must revert
        // because paused() truthfully reports the paused state to the whenNotPaused guard.
        assertTrue(!secondOk, "second pause must revert while paused");
    }
}

contract MockConfig {
    function hasRole(bytes32, address) external pure returns (bool) {
        return true;
    }
    function isSupportedAsset(address) external pure returns (bool) {
        return true;
    }
}
